export function ServerState({
  resourceName = "{{resourceName}}",
  freshness = "{{freshness}}",
  accent = "{{accent}}",
  showOwner = {{showOwner}},
}) {
  const statuses = {
    fresh: "Fresh \u2014 matches the server exactly",
    refetching: "Refetching \u2014 showing the old copy while the new one loads",
    stale: "Stale \u2014 the server has moved on since this copy was cached",
  };
  const node = (active) => ({ flex: 1, textAlign: "center", padding: "10px 4px", borderRadius: 8, fontSize: 11, fontWeight: 700, background: active ? accent : "#24143010" });
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <span style={node(freshness === "refetching")}>Server</span>
        <span style={{ color: "#24143060" }}>&rarr;</span>
        <span style={node(freshness !== "refetching")}>Client copy</span>
      </div>
      <p style={{ margin: "0 0 8px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>{resourceName}</p>
      <p style={{ margin: 0, fontSize: 11, fontWeight: 600 }}>{statuses[freshness]}</p>
      {showOwner && <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>The client copy is never the source of truth &mdash; the server always is.</p>}
    </div>
  );
}
